#include "stdlib/math/base/special/versin.h"
#include "stdlib/math/base/special/sin.h"

/**
* Computes the versed sine.
*
* @param x    input value (in radians)
* @return     versed sine
*
* @example
* double y = stdlib_base_versin( 0.0 );
* // returns 0.0
*/
double stdlib_base_versin( const double x ) {
	double s;

	// Use the half-angle identity `1 - cos(x) = 2*sin(x/2)^2`, as evaluating `1 - cos(x)` directly loses all significant digits when `cos(x)` is close to one (e.g., for small `x`):
	s = stdlib_base_sin( x / 2.0 );
	return 2.0 * s * s;
}
